var COMMAND_RE = /^\/([a-z0-9_]+)(?:@\S+)?(?:\s+([\s\S]*))?$/i;
async function dispatchCommand(thread, message) {
  const match = COMMAND_RE.exec(message.text?.trim() ?? "");
  if (!match)
    return false;
  const [, name24, rest = ""] = match;
  const command = byName.get(name24.toLowerCase());
  if (!command) {
    await thread.post(`Unknown command /${name24}. Try /help.`);
    return true;
  }
  const args = rest.trim() === "" ? [] : rest.trim().split(/\s+/);
  await command.handler({ thread, message, args });
  return true;
}

