function reportLlmFailure(scope, model, error51) {
  const e = error51;
  console.error("LLM_GENERATION_FAILED", JSON.stringify({
    scope,
    model,
    name: e?.name ?? null,
    statusCode: e?.statusCode ?? null,
    message: e?.message ?? String(error51),
    responseBody: typeof e?.responseBody === "string" ? e.responseBody.slice(0, 500) : null
  }));
}

