var UserPersonaSchema = exports_external.object({
  bullets: exports_external.array(exports_external.string()).optional(),
  nicknames: exports_external.array(exports_external.string()).optional(),
  rivalries: exports_external.array(exports_external.string()).optional(),
  team: exports_external.string().optional(),
  tone: exports_external.string().optional()
});
function parsePersona(raw) {
  if (raw == null)
    return;
  const result = UserPersonaSchema.safeParse(raw);
  return result.success ? result.data : undefined;
}
function personaFragments(p2) {
  const clean = (xs) => (xs ?? []).map((x2) => x2.trim()).filter(Boolean);
  const frags = [];
  const nicknames = clean(p2.nicknames);
  if (nicknames.length)
    frags.push(`goes by ${nicknames.map((n) => `"${n}"`).join(", ")}`);
  if (p2.team?.trim())
    frags.push(p2.team.trim());
  const rivalries = clean(p2.rivalries);
  if (rivalries.length)
    frags.push(`loves needling ${rivalries.join(", ")}`);
  frags.push(...clean(p2.bullets));
  if (p2.tone?.trim())
    frags.push(`(${p2.tone.trim()})`);
  return frags;
}
function personaPromptBlock(users2) {
  const entries = [];
  for (const u2 of users2) {
    const persona = parsePersona(u2.persona);
    if (!persona)
      continue;
    const frags = personaFragments(persona);
    if (frags.length === 0)
      continue;
    entries.push(`- ${displayName(u2)}: ${frags.join("; ")}.`);
  }
  if (entries.length === 0)
    return "";
  return [
    "Persona notes — personalize the trash talk for these players where it fits naturally",
    "(use a nickname, poke their team, reference a rivalry). Skip any note that doesn't land,",
    "and never apply notes to a player who has none:",
    ...entries
  ].join(`
`);
}

