async function buildSettlementRecap(settlements, voidedBets) {
  const { marketInfo, userById } = await loadSettlementContext(settlements);
  const { winners, losers } = describeSettledBets(settlements, marketInfo, userById);
  const { body, model, facts } = await generateSettlementRecap(winners, losers, voidedBets, [...userById.values()]);
  const net2 = winners.reduce((n, w2) => n + w2.swing, 0) - losers.reduce((n, l) => n + l.swing, 0);
  return { body, model, facts, users: [...userById.values()], net: net2 };
}
async function loadSettlementContext(settlements) {
  const tickers = settlements.map((s) => s.marketTicker);
  const context2 = tickers.length ? await db.select({ ticker: markets.ticker, outcome: markets.outcome, title: events.title }).from(markets).innerJoin(events, eq(events.eventTicker, markets.eventTicker)).where(inArray(markets.ticker, tickers)) : [];
  const marketInfo = new Map(context2.map((c2) => [c2.ticker, c2]));
  const userIds = [...new Set(settlements.flatMap((s) => s.bets.map((b3) => b3.userId)))];
  const userRows = userIds.length ? await db.select().from(users).where(inArray(users.id, userIds)) : [];
  const userById = new Map(userRows.map((u2) => [u2.id, u2]));
  return { marketInfo, userById };
}
function describeSettledBets(settlements, marketInfo, userById) {
  const winners = [];
  const losers = [];
  for (const settlement of settlements) {
    for (const bet2 of settlement.bets) {
      const user = userById.get(bet2.userId);
      const name24 = user ? displayName(user) : "A mystery bettor";
      const info = marketInfo.get(settlement.marketTicker);
      const pick2 = info ? `${bet2.side === "yes" ? "on" : "against"} ${info.outcome} (${info.title})` : `on ${settlement.marketTicker}`;
      if (bet2.won) {
        const payoutNet = bet2.contracts * 100 - bet2.costCents;
        winners.push({ name: name24, pick: pick2, stake: bet2.costCents, payoutNet, swing: payoutNet });
      } else {
        losers.push({ name: name24, pick: pick2, stake: bet2.costCents, payoutNet: 0, swing: bet2.costCents });
      }
    }
  }
  winners.sort((a, b3) => b3.swing - a.swing);
  losers.sort((a, b3) => b3.swing - a.swing);
  return { winners, losers };
}
var SETTLEMENT_SYSTEM = [
  "You are the resident hype-man and trash-talk commissioner for a group of friends who bet",
  "fake money against a prediction market through a Telegram bot. Bets just settled and it's",
  "your job to break the news to the group chat.",
  "",
  "Tone: fun, playful, light-hearted — like joking around with good friends. Hype the winners,",
  "and give the losers a good-natured ribbing for the bets that didn't pan out. Keep it cheeky",
  "and keep the energy up, but never mean-spirited or personal — all in good fun.",
  "",
  "Rules:",
  "- Use ONLY the names, picks, and dollar figures provided. Never invent players, bets, or numbers.",
  '- Copy dollar amounts EXACTLY as written (e.g. "+$90", "$50"). Do not recompute or round them.',
  "- Refer to players by the exact display names given, spelled exactly.",
  "- Write ONE flowing block of trash talk — not a list. Roughly a sentence per notable bet.",
  "- 150 words max. Open with a punchy line, then go bet by bet.",
  "- A little Telegram markdown (**bold** the names and dollar swings) and a few emoji, used sparingly.",
  "- No title or header, no sign-off — just the trash talk."
].join(`
`);
function settlementFacts(winners, losers, voidedBets) {
  const lines = ["Bets just settled. Here's the damage:"];
  if (winners.length) {
    lines.push("", "Winners:");
    for (const w2 of winners) {
      lines.push(`- ${w2.name} bet ${formatDollars(w2.stake)} ${w2.pick} and WON, netting +${formatDollars(w2.payoutNet)}.`);
    }
  }
  if (losers.length) {
    lines.push("", "Losers:");
    for (const l of losers) {
      lines.push(`- ${l.name} bet ${formatDollars(l.stake)} ${l.pick} and LOST the whole ${formatDollars(l.stake)}.`);
    }
  }
  if (voidedBets > 0) {
    lines.push("", `${voidedBets} bet${voidedBets === 1 ? "" : "s"} got voided and refunded — no winner, no loser.`);
  }
  return lines.join(`
`);
}
async function generateSettlementRecap(winners, losers, voidedBets, users2) {
  const facts = settlementFacts(winners, losers, voidedBets);
  const personas = personaPromptBlock(users2);
  const prompt = personas ? `Here's what just settled:

${facts}

${personas}

Break the news.` : `Here's what just settled:

${facts}

Break the news.`;
  try {
    const { text: text8 } = await generateText({
      model: anthropic(SETTLEMENT_MODEL),
      system: SETTLEMENT_SYSTEM,
      prompt,
      temperature: 0.9,
      maxOutputTokens: 400
    });
    const trimmed = text8.trim();
    if (trimmed)
      return { body: trimmed, model: SETTLEMENT_MODEL, facts };
    throw new Error("model returned an empty completion");
  } catch (error51) {
    reportLlmFailure("settlement-recap", SETTLEMENT_MODEL, error51);
    return { body: fallbackSettlementRecap(winners, losers, voidedBets), model: "fallback", facts };
  }
}
function fallbackSettlementRecap(winners, losers, voidedBets) {
  const blocks = [];
  if (winners.length) {
    const lines = winners.map((w2) => `• ${w2.name} ${pickRandom(VICTORY_PHRASES)} betting ${formatDollars(w2.stake)} ${w2.pick} and made **+${formatDollars(w2.payoutNet)}**`);
    blocks.push(["\uD83C\uDFC6 **Winner's circle:**", ...lines].join(`
`));
  }
  if (losers.length) {
    const lines = losers.map((l) => `• ${l.name} ${pickRandom(SHAME_PHRASES)} betting ${formatDollars(l.stake)} ${l.pick}`);
    blocks.push(["\uD83D\uDC80 **Loser's circle:**", ...lines].join(`
`));
  }
  if (voidedBets > 0) {
    blocks.push(`♻️ ${voidedBets} bet${voidedBets === 1 ? "" : "s"} voided and refunded.`);
  }
  return blocks.join(`

`);
}

// src/api/sync.ts
async function GET(request) {
  const auth = request.headers.get("authorization");
  if (!process.env.CRON_SECRET || auth !== `Bearer ${process.env.CRON_SECRET}`) {
    return new Response("Unauthorized", { status: 401 });
  }
  const { bettableAlerts, ...stats } = await syncAll();
  let announcedThreads = 0;
  const claimed = await claimUnannouncedSettlements();
  if (claimed.claimedBetIds.length > 0) {
    try {
      announcedThreads = await announceSettlements(claimed.settlements, claimed.voidedBets);
    } catch (error51) {
      console.error("settlement announcement failed:", error51);
    }
    if (announcedThreads === 0)
      await releaseAnnouncements(claimed.claimedBetIds);
  }
  let alertedThreads = 0;
  if (bettableAlerts.length > 0) {
    try {
      alertedThreads = await announceBettableAlerts(bettableAlerts);
    } catch (error51) {
      console.error("bettable alert announcement failed:", error51);
    }
    if (alertedThreads === 0) {
      await releaseBettableAlerts(bettableAlerts.map((a) => a.eventTicker));
    }
  }
  return Response.json({ ...stats, announcedThreads, alertedThreads });
}
